import{_ as a,o as r,c as t,a5 as o}from"./chunks/framework.CslsFoWx.js";const p=JSON.parse('{"title":"Serveur MCP Vendora — conception et tâches (planifié, pas commencé)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/mcp-vendora.md","filePath":"generated/architecture/mcp-vendora.md","lastUpdated":null}'),s={name:"architecture/mcp-vendora.md"};function n(i,e,l,c,d,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<div><h1 id="serveur-mcp-vendora-—-conception-et-taches-planifie-pas-commence" tabindex="-1">Serveur MCP Vendora — conception et tâches (planifié, pas commencé) <a class="header-anchor" href="#serveur-mcp-vendora-—-conception-et-taches-planifie-pas-commence" aria-label="Permalink to &quot;Serveur MCP Vendora — conception et tâches (planifié, pas commencé)&quot;">​</a></h1><blockquote><p><strong>Statut : à faire plus tard.</strong> Plan noté le 08/11/2026. Il sera revu et amélioré avant de démarrer ; rien n&#39;est encore développé. Suivi des tâches : <a href="/VendoraSystem-docs/suivi/journal">TRACKING › MCP Vendora</a>.</p></blockquote><h2 id="_1-l-idee" tabindex="-1">1. L&#39;idée <a class="header-anchor" href="#_1-l-idee" aria-label="Permalink to &quot;1. L&#39;idée&quot;">​</a></h2><p><strong>MCP (Model Context Protocol)</strong> est un protocole ouvert qui donne à un assistant IA (Claude, ChatGPT…) des <strong>outils</strong> et des <strong>données</strong> venant d&#39;un logiciel, dans un format standard. Un serveur MCP déclare des outils (nom, description, paramètres) ; l&#39;assistant décide seul quand les appeler, le serveur fait le travail et renvoie le résultat.</p><p>Pour Vendora : un commerçant branche son assistant sur son commerce et lui demande « Combien j&#39;ai vendu hier ? », « Quels produits sont en rupture ? », « Pourquoi ma marge baisse ? ». C&#39;est le lot <strong>A8</strong> de l&#39;<a href="/VendoraSystem-docs/commercial/etude-gaas">étude GaaS</a> : le même registre d&#39;outils sert nos futurs agents et l&#39;assistant du commerçant.</p><h2 id="_2-principes-d-architecture" tabindex="-1">2. Principes d&#39;architecture <a class="header-anchor" href="#_2-principes-d-architecture" aria-label="Permalink to &quot;2. Principes d&#39;architecture&quot;">​</a></h2><ul><li><strong>Service séparé <code>mcp/</code></strong> dans le monorepo, <strong>client de l&#39;<a href="/VendoraSystem-docs/architecture/api-publique">API publique</a></strong> comme le back-office : jamais d&#39;accès direct à la base, jamais le rôle <code>pos_platform</code> ; les règles métier restent dans le serveur.</li><li><strong>Langage proposé : Kotlin</strong> (SDK MCP officiel, cohérent avec le futur service <code>agents/</code>) — alternative : TypeScript (SDK le plus mûr). À trancher.</li><li><strong>Deux transports</strong> : <strong>stdio</strong> (Claude Desktop / Claude Code d&#39;un commerçant ou d&#39;un intégrateur) et <strong>HTTP</strong> hébergé (<code>mcp.vendora…</code>) pour les connecteurs claude.ai / ChatGPT.</li><li><strong>Sans état</strong> : chaque appel porte la clé (puis le jeton OAuth) du commerçant.</li></ul><h2 id="_3-taches-par-lot" tabindex="-1">3. Tâches par lot <a class="header-anchor" href="#_3-taches-par-lot" aria-label="Permalink to &quot;3. Tâches par lot&quot;">​</a></h2><h3 id="m0-—-prerequis-serveur-≈-1-semaine" tabindex="-1">M0 — Prérequis serveur (≈ 1 semaine) <a class="header-anchor" href="#m0-—-prerequis-serveur-≈-1-semaine" aria-label="Permalink to &quot;M0 — Prérequis serveur (≈ 1 semaine)&quot;">​</a></h3><ul><li>[ ] Portées fines sur les clés d&#39;API (<code>catalog:read</code>, <code>reports:read</code>, <code>inventory:read</code>, <code>customers:read</code>, <code>purchases:write</code>…), READ / WRITE conservés pour la compatibilité.</li><li>[ ] Restriction d&#39;une clé à un ou plusieurs magasins.</li><li>[ ] Type de clé « Assistant IA » : portées lecture préréglées, débit plus bas, expiration par défaut (90 jours).</li><li>[ ] Acteur <code>AGENT</code> dans le journal d&#39;audit (action faite par un assistant, au nom de quel utilisateur).</li><li>[ ] Droit <code>MCP_ACCESS</code> dans les formules (console) ; arrêt d&#39;urgence par commerce et global.</li><li>[ ] Tests d&#39;intégration ; <code>API-PUBLIQUE.md</code> et spec 13 à jour.</li></ul><h3 id="m1-—-serveur-mcp-en-lecture-seule-≈-1-5-semaine" tabindex="-1">M1 — Serveur MCP en lecture seule (≈ 1,5 semaine) <a class="header-anchor" href="#m1-—-serveur-mcp-en-lecture-seule-≈-1-5-semaine" aria-label="Permalink to &quot;M1 — Serveur MCP en lecture seule (≈ 1,5 semaine)&quot;">​</a></h3><ul><li>[ ] Outils : <code>magasins</code>, <code>ventes</code> (jour, période, par heure, par moyen de paiement), <code>meilleurs_produits</code>, <code>produits_dormants</code>, <code>marges</code>, <code>food_cost</code>, <code>stock_bas</code>, <code>valeur_stock</code>, <code>sessions_et_z</code>, <code>bons_de_commande</code>, <code>etat_des_appareils</code>, <code>rechercher_produit</code> ; <code>alertes_anti_fraude</code> en option (sensible).</li><li>[ ] Montants renvoyés <strong>formatés</strong> (« 1 234,50 € ») en plus des unités mineures, avec la devise.</li><li>[ ] <code>dataFreshAt</code> dans chaque réponse ; au-delà de 15 min, l&#39;outil le signale au lieu de laisser deviner.</li><li>[ ] Pas de données personnelles par défaut (clients et salariés pseudonymisés ; noms et coordonnées seulement avec la portée <code>customers:read</code> explicitement accordée).</li><li>[ ] Prompts prêts (« Bilan de ma journée », « Que commander cette semaine ? », « Pourquoi ma marge baisse ? ») et ressources (pages du <a href="https://vendora-aide.onrender.com" target="_blank" rel="noreferrer">centre d&#39;aide</a>).</li><li>[ ] Tests par outil contre un faux serveur, test de bout en bout avec MCP Inspector, preuve réelle (Claude Code branché sur le serveur de dev, commerce de démo).</li></ul><h3 id="m2-—-produit-et-hebergement-≈-1-semaine" tabindex="-1">M2 — Produit et hébergement (≈ 1 semaine) <a class="header-anchor" href="#m2-—-produit-et-hebergement-≈-1-semaine" aria-label="Permalink to &quot;M2 — Produit et hébergement (≈ 1 semaine)&quot;">​</a></h3><ul><li>[ ] Back-office › Réglages › <strong>Assistant IA</strong> : créer une clé « Assistant IA » (portées, magasins), configuration prête à copier pour Claude Desktop, Claude Code et ChatGPT, activité dans le journal, couper d&#39;un clic.</li><li>[ ] Centre d&#39;aide : « Brancher votre assistant IA » (captures, vidéo).</li><li>[ ] Service Render <code>vendora-mcp-staging</code>.</li><li>[ ] Spec <strong>18-mcp</strong>, site (fonctionnalités, vitrine), README.</li></ul><h3 id="m3-—-connexion-oauth-≈-1-5-semaine-peut-attendre" tabindex="-1">M3 — Connexion OAuth (≈ 1,5 semaine, peut attendre) <a class="header-anchor" href="#m3-—-connexion-oauth-≈-1-5-semaine-peut-attendre" aria-label="Permalink to &quot;M3 — Connexion OAuth (≈ 1,5 semaine, peut attendre)&quot;">​</a></h3><ul><li>[ ] OAuth 2.1 (exigé par les connecteurs claude.ai / ChatGPT) : le commerçant se connecte, choisit magasins et portées, sans copier de clé ; écran de consentement, jetons courts révocables au back-office.</li></ul><h3 id="m4-—-ecriture-encadree-apres-le-lot-gaas-a2" tabindex="-1">M4 — Écriture encadrée (après le lot GaaS A2) <a class="header-anchor" href="#m4-—-ecriture-encadree-apres-le-lot-gaas-a2" aria-label="Permalink to &quot;M4 — Écriture encadrée (après le lot GaaS A2)&quot;">​</a></h3><ul><li>[ ] Aucune écriture directe : les outils d&#39;écriture <strong>créent des propositions</strong> (<code>agent_proposals</code>) — bon de commande brouillon, changement de prix, acquittement d&#39;alerte — validées par le gérant (back-office, app, PIN manager).</li></ul><h2 id="_4-garde-fous-des-m1" tabindex="-1">4. Garde-fous (dès M1) <a class="header-anchor" href="#_4-garde-fous-des-m1" aria-label="Permalink to &quot;4. Garde-fous (dès M1)&quot;">​</a></h2><ul><li>Lecture seule tant que M4 n&#39;existe pas ; paiement, fiscal en écriture, PIN, clés et délégations hors d&#39;atteinte (comme l&#39;API publique).</li><li><strong>Injection de consignes</strong> : noms de produits, notes fournisseurs, messages de clients sont des <strong>données</strong>, jamais des instructions ; les réponses des outils les balisent comme telles.</li><li>Débit limité par clé, audit de chaque appel, révocation immédiate.</li></ul><h2 id="_5-effort" tabindex="-1">5. Effort <a class="header-anchor" href="#_5-effort" aria-label="Permalink to &quot;5. Effort&quot;">​</a></h2><p>M0 → M2 ≈ <strong>3,5 semaines</strong> (MCP lecture seule utilisable avec une clé à copier) ; + M3 ≈ 1,5 semaine (connecteurs « en un clic ») ; M4 avec la suite GaaS.</p><h2 id="_6-decisions-a-prendre-avant-de-demarrer" tabindex="-1">6. Décisions à prendre avant de démarrer <a class="header-anchor" href="#_6-decisions-a-prendre-avant-de-demarrer" aria-label="Permalink to &quot;6. Décisions à prendre avant de démarrer&quot;">​</a></h2><ol><li>Langage : Kotlin (recommandé) ou TypeScript.</li><li>Ordre : M0 → M2 d&#39;abord, M3 plus tard (recommandé), ou OAuth dès le départ.</li><li>Données clients : exclues de la v1 (recommandé) ou accessibles avec une portée explicite.</li><li>Commercial : inclus dans toutes les formules (lecture seule) ou réservé à une formule / un add-on.</li></ol></div>',1)])])}const h=a(s,[["render",n]]);export{p as __pageData,h as default};
